// Function Node: Build Worker Task List

const taskDivision = $json.body.taskDivision;
const workers = $json.body.workers;

// Create array of workers with their assigned tasks and ports
const workerTaskList = workers.map((worker) => {
  return {
    workerName: worker.workerName,
    port: worker.port,
    task: taskDivision['tasks'][worker.workerName],
    status: worker.status,
    pid: worker.pid
  };
});

return workerTaskList;

